// Code node "Lecture" (mode: Run Once for All Items)
// Reads Claude's JSON answer and attaches it to the original request.
// If the answer is unreadable, escalate for safety (never an automatic reply when in doubt).
const demandes = $('Demandes').all();
const sorties = [];

$input.all().forEach((item, i) => {
  // Claude may return a "thinking" block before the text: take the block of type "text".
  const bloc = (item.json.content ?? []).find((c) => c.type === 'text');
  const brut = bloc?.text ?? '';
  let r;
  try {
    const m = brut.match(/\{[\s\S]*\}/);
    r = JSON.parse(m ? m[0] : brut);
  } catch (e) {
    r = {
      procedure: 'ERREUR_JSON',
      decision: 'escalader',
      procedure_citee: '',
      raison: 'Unreadable answer, escalating for safety',
      brouillon: brut,
    };
  }
  sorties.push({
    json: {
      id: demandes[i].json.id,
      demande: demandes[i].json.demande,
      procedure: r.procedure,
      decision: r.decision,
      procedure_citee: r.procedure_citee,
      raison: r.raison,
      brouillon: r.brouillon,
      input_tokens: item.json.usage?.input_tokens ?? null,
      output_tokens: item.json.usage?.output_tokens ?? null,
    },
  });
});

return sorties;
